def convert(x):
    if isinstance(x, complex):
        r = abs(x)
        theta = math.phase(x)
        return (r, theta)
    elif isinstance(x, int) or isinstance(x, float):
        # Treat real number as complex with zero imaginary part
        c = complex(x, 0)
        r = abs(c)
        theta = math.phase(c)
        return (r, theta)
    else:
        raise TypeError("Input must be a complex number or a real number.")

