def tuple_intersection(tuple_list1, tuple_list2):
    """
    Find the intersection of tuples from two lists, ignoring order within tuples.

    Args:
        tuple_list1 (list): First list of tuples.
        tuple_list2 (list): Second list of tuples.

    Returns:
        set: A set containing tuples that exist in both lists, with elements sorted.
    """
    # Normalize each tuple by sorting its elements to ignore order within the tuple
    def normalize_tuple(t):
        return tuple(sorted(t))

    # Create sets of normalized tuples for efficient lookup
    set1 = {normalize_tuple(t) for t in tuple_list1}
    set2 = {normalize_tuple(t) for t in tuple_list2}

    # Find intersection of normalized tuples
    intersection_normalized = set1 & set2

    # Convert back to original format (sorted elements within each tuple)
    result = {tuple(sorted(t)) for t in intersection_normalized}

    return result

