def get_ludic(n: int) -> list[int]:
    """
    Returns a list of all lucid numbers smaller than or equal to n.

    A number is considered 'lucid' if the count of its divisors (including 1 and itself)
    is odd. This property holds true for prime numbers and the number 1.
    """
    def get_divisor_count(num: int) -> int:
        count = 0
        for i in range(1, num + 1):
            if num % i == 0:
                count += 1
        return count

    lucid_numbers = []
    for i in range(1, n + 1):
        if get_divisor_count(i) % 2 == 1:
            lucid_numbers.append(i)

    return lucid_numbers

