def remove_Occ(s: str, char: str) -> str:
    if len(s) <= 1:
        return s

    start = -1
    end = -1

    # Find first occurrence
    for i in range(len(s)):
        if s[i] == char:
            start = i
            break

    # Find last occurrence
    for i in range(len(s) - 1, -1, -1):
        if s[i] == char:
            end = i
            break

    if start == -1 or start == end:
        return s

    # Remove first and last occurrence
    result = s[:start] + s[start+1:end] + s[end+1:]
    return result

